import requests

url = "https://www.macrotrends.net/countries/JPN/japan/usd-jpy-exchange-rate-historical-data"
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
}

try:
    response = requests.get(url, headers=headers, timeout=15)
    print(f"Status: {response.status_code}")
    if response.status_code == 200:
        # Find table with March 2025 data
        if '2025' in response.text:
            import re
            matches = re.findall(r'2025[^<]{10,50}', response.text)
            for m in matches[:20]:
                print(m)
except Exception as e:
    print(f"Error: {e}")
EOF
